"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { shinyButtonDefaults, type ShinyButtonSpecProps } from "../generated/shiny-button.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";

export interface ShinyButtonProps extends ShinyButtonSpecProps, Omit<ButtonProps, keyof ShinyButtonSpecProps> {}

/** A button with a band of light that sweeps across it on hover and focus, and slowly at rest. Builds on Button. */
export const ShinyButton = forwardRef<HTMLButtonElement, ShinyButtonProps>(function ShinyButton(
  { children, duration = shinyButtonDefaults.duration, isPaused = shinyButtonDefaults.isPaused, className, style, ...rest },
  ref,
) {
  return (
    <Button
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("rdm-shiny relative overflow-hidden", className)}
      style={(values) => ({ ...motionVars({ "--rdm-d": `${duration}s` }), ...(typeof style === "function" ? style(values) : style) })}
    >
      <span className="relative z-[1] inline-flex items-center gap-2">{children}</span>
      <span aria-hidden="true" className="rdm-shiny-sweep" />
    </Button>
  );
});

// Generated by rdloom codegen from specs/shiny-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const shinyButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const shinyButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button with a band of light that sweeps across its surface on hover and keyboard focus, and slowly now and then at rest. Builds on Button. */
export interface ShinyButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Seconds for one sweep at rest, including the pause before the next.
   * @default 3.6
   */
  duration?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const shinyButtonDefaults = {
  variant: "primary",
  size: "md",
  duration: 3.6,
  isPaused: false,
  isDisabled: false,
  isLoading: false,
} as const;

export const shinyButtonMeta = {
  "name": "ShinyButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
